def materialize(inputs, state, events):
    state.clear()
    values = {}
    for name in ["left", "right"]:
        events.extend([name, name + "_clean"])
        if inputs[name] < 0:
            raise ValueError("negative source")
        values[name] = inputs[name] * 2
    events.append("publish")
    return values["left"] + values["right"]
